#include <iostream>
#include <vector>
#include <queue>
using namespace std;

struct Pair {
    int location;
    int dist;
};

int main() {
    int n, m;
    cin >> n >> m;

    if (n >= m) {
        cout << n - m << endl;
    } else {
        vector<bool> visited(m + 2, false);

        queue<Pair> q;
        q.push({n, 0});

        int ans = 0;
        visited[n] = true;
        while (!q.empty()) {
            Pair tmp = q.front();
            q.pop();

            if (tmp.location == m) {
                ans = tmp.dist;
                break;
            }

            if (tmp.location * 2 <= m + 1 && !visited[tmp.location * 2]) {
                q.push({tmp.location * 2, tmp.dist + 1});
                visited[tmp.location * 2] = true;
            }
            if (tmp.location - 1 >= 0 && !visited[tmp.location - 1]) {
                q.push({tmp.location - 1, tmp.dist + 1});
                visited[tmp.location - 1] = true;
            }
        }

        cout << ans << endl;
    }

    return 0;
}
